    for char in paren_string:
        if char == "(":
            if current_group:
                groups.append(current_group)
            current_group = "("
        elif char == ")":
            current_group += ")"
            groups.append(current_group)
            current_group = ""

    unique_groups = []  # Initialize list to store unique strings of separate groups
    for group in groups:
        unique_group = ""
        for char in group:
            if char in "()":
                unique_group += char
        if unique_group not in unique_groups:
            unique_groups.append(unique_group)

    return unique_groups

